const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1], N = 2 * n;
const node = (x) => (x > 0 ? 2 * (x - 1) : 2 * (-x - 1) + 1);
const g = Array.from({ length: N }, () => []), rg = Array.from({ length: N }, () => []);
for (let i = 0; i < m; i++) {
  const a = node(tok[2 + 2 * i]), b = node(tok[3 + 2 * i]);
  g[a ^ 1].push(b); rg[b].push(a ^ 1);
  g[b ^ 1].push(a); rg[a].push(b ^ 1);
}
const seen = new Array(N).fill(false), nxt = new Array(N).fill(0), order = [];
for (let s = 0; s < N; s++) {
  if (seen[s]) continue;
  seen[s] = true;
  const stack = [s];
  while (stack.length) {
    const v = stack[stack.length - 1];
    if (nxt[v] < g[v].length) {
      const to = g[v][nxt[v]++];
      if (!seen[to]) { seen[to] = true; stack.push(to); }
    } else { stack.pop(); order.push(v); }
  }
}
const comp = new Array(N).fill(-1);
let c = 0;
for (let i = order.length - 1; i >= 0; i--) {
  const s = order[i];
  if (comp[s] >= 0) continue;
  comp[s] = c;
  const stack = [s];
  while (stack.length) {
    const v = stack.pop();
    for (const to of rg[v]) if (comp[to] < 0) { comp[to] = c; stack.push(to); }
  }
  c++;
}
let ok = true;
for (let i = 0; i < n; i++) if (comp[2 * i] === comp[2 * i + 1]) ok = false;
console.log(ok ? "YES" : "NO");

