import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] g, rg;
    static boolean[] seen;
    static int[] comp;
    static List<Integer> order = new ArrayList<>();

    static void dfs1(int v) {
        seen[v] = true;
        for (int to : g[v]) if (!seen[to]) dfs1(to);
        order.add(v);
    }

    static void dfs2(int v, int c) {
        comp[v] = c;
        for (int to : rg[v]) if (comp[to] < 0) dfs2(to, c);
    }

    static int node(int x) {
        return x > 0 ? 2 * (x - 1) : 2 * (-x - 1) + 1;
    }

    public static void main(String[] args) throws Exception {
        Thread t = new Thread(null, () -> {
            try { run(); } catch (IOException e) { throw new RuntimeException(e); }
        }, "main", 1 << 26);
        t.start();
        t.join();
    }

    static void run() throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int N = 2 * n;
        g = new List[N];
        rg = new List[N];
        for (int i = 0; i < N; i++) { g[i] = new ArrayList<>(); rg[i] = new ArrayList<>(); }
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int a = node((int) in.nval);
            in.nextToken();
            int b = node((int) in.nval);
            g[a ^ 1].add(b); rg[b].add(a ^ 1);
            g[b ^ 1].add(a); rg[a].add(b ^ 1);
        }
        seen = new boolean[N];
        comp = new int[N];
        Arrays.fill(comp, -1);
        for (int s = 0; s < N; s++) if (!seen[s]) dfs1(s);
        int c = 0;
        for (int i = order.size() - 1; i >= 0; i--) {
            int s = order.get(i);
            if (comp[s] < 0) dfs2(s, c++);
        }
        boolean ok = true;
        for (int i = 0; i < n; i++) if (comp[2 * i] == comp[2 * i + 1]) ok = false;
        System.out.println(ok ? "YES" : "NO");
    }
}

