#include <bits/stdc++.h>
using namespace std;
vector<vector<int>> g, rg;
vector<bool> seen;
vector<int> comp_, order_;

int node(int x) { return x > 0 ? 2 * (x - 1) : 2 * (-x - 1) + 1; }
void dfs1(int v) {
    seen[v] = true;
    for (int to : g[v]) if (!seen[to]) dfs1(to);
    order_.push_back(v);
}
void dfs2(int v, int c) {
    comp_[v] = c;
    for (int to : rg[v]) if (comp_[to] < 0) dfs2(to, c);
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    int N = 2 * n;
    g.assign(N, {});
    rg.assign(N, {});
    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        int a = node(x), b = node(y);
        g[a ^ 1].push_back(b); rg[b].push_back(a ^ 1);
        g[b ^ 1].push_back(a); rg[a].push_back(b ^ 1);
    }
    seen.assign(N, false);
    comp_.assign(N, -1);
    for (int s = 0; s < N; s++) if (!seen[s]) dfs1(s);
    int c = 0;
    for (int i = (int)order_.size() - 1; i >= 0; i--)
        if (comp_[order_[i]] < 0) dfs2(order_[i], c++);
    bool ok = true;
    for (int i = 0; i < n; i++) if (comp_[2 * i] == comp_[2 * i + 1]) ok = false;
    puts(ok ? "YES" : "NO");
    return 0;
}
